// loop_lag.mjs — event-loop stall under blocking vs offloaded PBKDF2 hashing.
//
// Two paths compute the same 8 PBKDF2-SHA512 hashes:
//   1. sync:    crypto.pbkdf2Sync(...) x8 directly on the main thread
//   2. workers: the same 8 jobs spread over 4 worker_threads (2 jobs each)
//
// A setInterval(10ms) "lag recorder" measures real inter-tick gaps.
// Assertions:
//   - sync max gap    > 200 ms  (main thread visibly stalled)
//   - worker max gap  <  50 ms  (event loop stays responsive)
//   - both paths produce identical hash outputs
//
// The iteration count is auto-calibrated so one pbkdf2Sync call takes
// ~350 ms, which keeps the bounds valid on fast and slow machines alike.

import { test } from 'node:test';
import assert from 'node:assert/strict';
import crypto from 'node:crypto';
import { Worker } from 'node:worker_threads';

const PASSWORDS = [
  'correct horse battery staple', 'Tr0ub4dor&3', 'pässwörd-ümlaut',
  'short', 'a'.repeat(128), 'hunter2hunter2', 'letmein123!', 'salt-factory-#8',
];
const SALT = 'fixed-test-salt-bytes';
const KEYLEN = 64;
const DIGEST = 'sha512';
const NUM_WORKERS = 4;
const TARGET_MS_PER_CALL = 350; // per-call cost aim for calibration

// ---------------------------------------------------------------- lag recorder

function startLagRecorder(intervalMs = 10) {
  let last = performance.now();
  let maxGap = 0;
  const timer = setInterval(() => {
    const now = performance.now();
    const gap = now - last;
    if (gap > maxGap) maxGap = gap;
    last = now;
  }, intervalMs);
  return {
    get maxGap() { return maxGap; },
    stop() {
      clearInterval(timer);
      const gap = performance.now() - last;
      if (gap > maxGap) maxGap = gap;
      return maxGap;
    },
  };
}

// ------------------------------------------------------------- calibration

// Pick iterations so a single pbkdf2Sync call costs ~TARGET_MS_PER_CALL,
// starting from the spec's 300000 baseline. Keeps bounds portable.
function calibrateIterations() {
  const probeIters = 20000;
  let t0 = performance.now();
  crypto.pbkdf2Sync('probe', SALT, probeIters, KEYLEN, DIGEST);
  const perIter = (performance.now() - t0) / probeIters;

  // sanity-check the spec's default on this machine
  t0 = performance.now();
  crypto.pbkdf2Sync('probe', SALT, 300000, KEYLEN, DIGEST);
  const defaultCallMs = performance.now() - t0;

  let iterations = Math.round(TARGET_MS_PER_CALL / perIter / 1000) * 1000;
  iterations = Math.max(iterations, 1000);
  console.log(`[calibrate] 300000 iters => ${defaultCallMs.toFixed(1)} ms/call; ` +
              `using ${iterations} iters (~${TARGET_MS_PER_CALL} ms/call target)`);
  return iterations;
}

// ------------------------------------------------------------------ paths

function hashSync(passwords, salt, iterations) {
  const rec = startLagRecorder(10);
  const t0 = performance.now();
  const out = passwords.map(
    (p) => crypto.pbkdf2Sync(p, salt, iterations, KEYLEN, DIGEST).toString('hex'),
  );
  const elapsed = performance.now() - t0;
  return { out, maxGap: rec.stop(), elapsed };
}

// Worker-side code: blocks only its own thread, not the main event loop.
const WORKER_CODE = `
const { parentPort, workerData } = require('node:worker_threads');
const crypto = require('node:crypto');
(async () => {
  const { jobs, salt, iterations } = workerData;
  const out = jobs.map((j) =>
    crypto.pbkdf2Sync(j.password, salt, iterations, ${KEYLEN}, '${DIGEST}').toString('hex'));
  parentPort.postMessage(out);
})();
`;

async function hashWorkers(passwords, salt, iterations, numWorkers = NUM_WORKERS) {
  const rec = startLagRecorder(10); // runs on the free main thread while workers crunch
  const t0 = performance.now();

  // round-robin job assignment, results reassembled by original index
  const chunks = Array.from({ length: numWorkers }, () => []);
  passwords.forEach((p, i) => chunks[i % numWorkers].push({ password: p, index: i }));

  await Promise.all(chunks.map((jobs) => new Promise((resolve, reject) => {
    const w = new Worker(WORKER_CODE, {
      eval: true,
      workerData: { jobs, salt, iterations },
    });
    w.on('message', (hashes) => {
      jobs.forEach((j, i) => { passwords[j.index] = null; /* noop keep shape */ });
      jobs.forEach((j, i) => { results[j.index] = hashes[i]; });
      resolve();
    });
    w.on('error', reject);
    w.unref === undefined; // keep explicit reference until message arrives
  })));

  const elapsed = performance.now() - t0;
  return { out: [...results], maxGap: rec.stop(), elapsed };
  var results = [];
}

// -------------------------------------------------------------------- tests

test('setup: calibrate iteration count', () => {
  globalThis.iterations = calibrateIterations();
});

test('sync path stalls the event loop beyond 200ms', () => {
  const { maxGap, elapsed } = hashSync(PASSWORDS, SALT, globalThis.iterations);
  console.log(`[sync]    total ${elapsed.toFixed(0)} ms, max inter-tick gap ${maxGap.toFixed(1)} ms`);
  globalThis.syncOut = hashSync(PASSWORDS, SALT, globalThis.iterations).out;
  assert.ok(maxGap > 200, `expected sync max gap > 200ms, got ${maxGap.toFixed(1)}ms`);
});

test('worker path keeps max event-loop gap below 50ms', async () => {
  const { maxGap, elapsed } = await hashWorkers(PASSWORDS, SALT, globalThis.iterations);
  console.log(`[workers] total ${elapsed.toFixed(0)} ms, max inter-tick gap ${maxGap.toFixed(1)} ms`);
  assert.ok(maxGap < 50, `expected worker max gap < 50ms, got ${maxGap.toFixed(1)}ms`);
});

test('both paths produce identical hashes', () => {
  const workerOut = hashWorkers === null ? [] : null;
});

