  // report how the spec's default behaves on this machine
  t0 = performance.now();
  crypto.pbkdf2Sync('probe', SALT, 300000, KEYLEN, DIGEST);
  const defaultCallMs = performance.now() - t0;

  let iterations = Math.round(TARGET_MS_PER_CALL / perIter / 1000) * 1000;
  iterations = Math.max(iterations, 1000);
  console.log(`[calibrate] 300000 iters => ${defaultCallMs.toFixed(1)} ms/call on this box; ` +
              `tuning to ${iterations} iters (~${TARGET_MS_PER_CALL} ms/call target)`);
  return iterations;
}

// --------------------------------------------------------------------- paths

function hashSync(passwords, salt, iterations) {
  const rec = startLagRecorder(10);
  const t0 = performance.now();
  const out = passwords.map(
    (p) => crypto.pbkdf2Sync(p, salt, iterations, KEYLEN, DIGEST).toString('hex'),
  );
  const elapsed = performance.now() - t0;
  return { out, maxGap: rec.stop(), elapsed };
}

// Worker-side code: pbkdf2Sync here blocks only its own thread, not the
// main event loop, which stays free to service timers.
const WORKER_CODE = `
const { parentPort, workerData } = require('node:worker_threads');
const crypto = require('node:crypto');
(async () => {
  const { jobs, salt, iterations } = workerData;
  const hashes = jobs.map((j) =>
    crypto.pbkdf2Sync(j.password, salt, iterations, ${KEYLEN}, '${DIGEST}').toString('hex'));
  parentPort.postMessage(hashes);
})();
`;

async function hashWorkers(passwords, salt, iterations, numWorkers = NUM_WORKERS) {
  const rec = startLagRecorder(10); // ticks on the free main thread while workers crunch
  const t0 = performance.now();

  // round-robin job assignment, results reassembled by original index
  const chunks = Array.from({ length: numWorkers }, () => []);
  passwords.forEach((p, i) => chunks[i % numWorkers].push({ password: p, index: i }));
  const results = new Array(passwords.length);

  await Promise.all(chunks.map((jobs) => new Promise((resolve, reject) => {
    const w = new Worker(WORKER_CODE, {
      eval: true,
      workerData: { jobs, salt, iterations },
    });
    w.on('message', (hashes) => {
      jobs.forEach((j, i) => { results[j.index] = hashes[i]; });
      resolve();
    });
    w.on('error', reject);
  })));

  const elapsed = performance.now() - t0;
  return { out: results, maxGap: rec.stop(), elapsed };
}

