test('setup: calibrate iteration count', () => {
  globalThis.iterations = calibrateIterations();
});

test('sync path stalls the event loop beyond 200ms', () => {
  const { out, maxGap, elapsed } = hashSync(PASSWORDS, SALT, globalThis.iterations);
  globalThis.syncOut = out;
  console.log(`[sync]    total ${elapsed.toFixed(0)} ms, max inter-tick gap ${maxGap.toFixed(1)} ms`);
  assert.ok(maxGap > 200, `expected sync max gap > 200ms, got ${maxGap.toFixed(1)}ms`);
